#!/usr/bin/env python3
from pathlib import Path
import hashlib,json,resource,subprocess,time
p=Path(__file__).resolve().parent;start=time.monotonic()
source='LIB "elim.lib";\nring r=0,(e,f,c),dp;\noption(redSB);\nideal I=-4*e^2 + 8*e*f + 24*e + 2*f^2 + 6*f + 15,-28*c^2 - 448*c*e*f - 816*c*e + 96*c*f + 60*c - 704*e*f^3 - 4560*e*f^2 - 7488*e*f + 552*e - 176*f^4 - 1152*f^3 - 3324*f^2 - 4872*f - 75,8*c^3 + 288*c^2*e*f + 744*c^2*e + 60*c^2*f + 528*c^2 + 1200*c*e*f^3 + 7824*c*e*f^2 + 15096*c*e*f + 4968*c*e + 300*c*f^4 + 1932*c*f^3 + 5520*c*f^2 + 8688*c*f + 2598*c - 288*e*f^5 - 12960*e*f^4 - 120144*e*f^3 - 458544*e*f^2 - 774732*e*f - 444318*e - 64*f^6 - 2916*f^5 - 28062*f^4 - 126886*f^3 - 324414*f^2 - 463719*f - 253322,176*c^4 + 11264*c^3*e*f + 11392*c^3*e - 6272*c^3*f - 13280*c^3 + 164864*c^2*e*f^3 + 898176*c^2*e*f^2 + 1342464*c^2*e*f + 347840*c^2*e + 41216*c^2*f^4 + 238720*c^2*f^3 + 720096*c^2*f^2 + 1026560*c^2*f + 372520*c^2 + 645120*c*e*f^5 + 7592704*c*e*f^4 + 35782656*c*e*f^3 + 84513024*c*e*f^2 + 101518336*c*e*f + 51588960*c*e + 143360*c*f^6 + 1733760*c*f^5 + 9323520*c*f^4 + 29230720*c*f^3 + 55726944*c*f^2 + 60018144*c*f + 29213736*c + 481280*e*f^7 + 9162496*e*f^6 + 69591552*e*f^5 + 267796480*e*f^4 + 526521344*e*f^3 + 403036896*e*f^2 - 151680384*e*f - 266125296*e + 108288*f^8 + 2089984*f^7 + 16876544*f^6 + 75479232*f^5 + 203066672*f^4 + 316818720*f^3 + 207862008*f^2 - 99718368*f - 151808253,-2080*c^5 - 208000*c^4*e*f - 435360*c^4*e + 720*c^4*f - 200160*c^4 - 4372800*c^3*e*f^3 - 29928960*c^3*e*f^2 - 66996960*c^3*e*f - 45230080*c^3*e - 1093200*c^3*f^4 - 7495760*c^3*f^3 - 24188160*c^3*f^2 - 41080720*c^3*f - 24890720*c^3 - 22567680*c^2*e*f^5 - 240863616*c^2*e*f^4 - 993103680*c^2*e*f^3 - 1885303872*c^2*e*f^2 - 1462841040*c^2*e*f - 218692656*c^2*e - 5015040*c^2*f^6 - 55193328*c^2*f^5 - 268062312*c^2*f^4 - 737888888*c^2*f^3 - 1162647384*c^2*f^2 - 849879024*c^2*f - 127838704*c^2 - 22502400*c*e*f^7 - 248260608*c*e*f^6 - 714911040*c*e*f^5 + 2045146816*c*e*f^4 + 18047488272*c*e*f^3 + 45841748160*c*e*f^2 + 51022692440*c*e*f + 20293688640*c*e - 5063040*c*f^8 - 57212928*c*f^7 - 207006768*c*f^6 + 151668000*c*f^5 + 3881059812*c*f^4 + 15118045428*c*f^3 + 29868627960*c*f^2 + 30150281220*c*f + 11585815170*c + 5240320*e*f^9 + 280304640*e*f^8 + 4646571264*e*f^7 + 38761402368*e*f^6 + 189803926080*e*f^5 + 575851069536*e*f^4 + 1080906778000*e*f^3 + 1187869738800*e*f^2 + 663525551340*e*f + 132803978070*e + 1177600*f^10 + 63317888*f^9 + 1068814656*f^8 + 9366788784*f^7 + 50531878712*f^6 + 180673095852*f^5 + 438685340074*f^4 + 711238425150*f^3 + 718621302570*f^2 + 385345034655*f + 75791580990;\npoly delta=-3*c + 2*e^2 + 2*e*f - f^2;\nprint("TRANSVERSE_COUPLED_BOUNDARY_STANDARD_START");ideal G=std(I);\nprint("TRANSVERSE_COUPLED_BOUNDARY_BASIS_SIZE");print(size(G));print("TRANSVERSE_COUPLED_BOUNDARY_BASIS");print(G);\nfor(int kk=1;kk<=4;kk++){poly remainderPoly=reduce(delta^kk,G);print("TRANSVERSE_COUPLED_BOUNDARY_POWER");print(kk);print(size(remainderPoly));if(remainderPoly==0){break;}}\nprint("END");quit;\n'
fpath=p/'transverse_coupled_boundary.sing';fpath.write_text(source)
log=p/'transverse_coupled_boundary_stdout.txt'
def limit():
 resource.setrlimit(resource.RLIMIT_AS,(768*1024*1024,768*1024*1024))
 resource.setrlimit(resource.RLIMIT_CPU,(30,30))
with log.open('w') as out:
 proc=subprocess.Popen(['/usr/bin/Singular','-q',str(fpath)],stdout=out,stderr=subprocess.STDOUT,preexec_fn=limit)
 print('LIVE_PID',proc.pid,flush=True);timeout=False
 try:code=proc.wait(timeout=30)
 except subprocess.TimeoutExpired:timeout=True;proc.kill();code=proc.wait()
result=log.read_text(errors='replace')
rec={'scope':'Exact coupled transverse line-conic first-ten moment chart, with explicit treatment of the M2 elimination denominator; no theorem from a timeout or nonzero target remainder.',
'wall_limit_seconds':30,'memory_limit_MiB':768,'terminal':True,'timed_out':timeout,'exit_code':code,'completed':code==0 and 'END' in result and '?' not in result,
'input_sha256':hashlib.sha256(fpath.read_bytes()).hexdigest(),'log_sha256':hashlib.sha256(log.read_bytes()).hexdigest(),'elapsed_seconds':time.monotonic()-start,'stdout_tail':result[-3000:]}
(p/'transverse_coupled_boundary_run.json').write_text(json.dumps(rec,indent=2)+'\n');print(json.dumps(rec,indent=2))
